// Overloaded Definitions: Same name, different parameters
void log_data(int i) {}
void log_data(double d) {}
void log_data(const char* s) {}
void log_data(int i, double d) {}

// Function Matching (Compiler Selects Best Fit)
log_data(42);         // Exact match: (int)
log_data(10.5);       // Exact match: (double)
log_data("Status");   // Exact match: (const char*)
log_data(1, 2.0);     // Exact match: (int, double)

// Implicit conversion/promotion
// If log_data(float f) was defined, log_data(10.5f) matches that.
// If no (double) exists, log_data(10.5) might use promotion rules.
// Overloading based solely on return type is illegal.
